const http = this.helpers.httpRequest;

const d = new Date();
d.setDate(d.getDate() - 7);
const since = d.toISOString().split('T')[0];

const KEYWORDS = [
  'electric','energia','iluminacion','subestacion','transformador','generador',
  'paneles solares','fotovoltaic','RETIE','montaje electrico','mantenimiento',
  'obras civiles','construccion','adecuacion','remodelacion',
  'infraestructura','vias','paviment','alcantarillado','edificio',
  'consultoria','interventoria',
  'diseno','ingenieria','arquitect','topograf',
  'suministro','dotacion','mobiliario','equipo',
  'software','sistemas','tecnologia','desarrollo',
  'reparacion','adecuacion'
];

const base = 'https://www.datos.gov.co/resource/jbjy-vk9h.json';
const params = '$select=nombre_entidad,descripcion_del_proceso,valor_del_contrato,fecha_de_firma,departamento,ciudad,modalidad_de_contratacion,tipo_de_contrato,urlproceso,id_contrato&$where=fecha_de_firma%20%3E=%20%27' + since + '%27&$order=fecha_de_firma%20DESC&$limit=30';
const url = base + '?' + params;

let data;
try {
  data = await http({ method:'GET', url: url });
} catch(e) {
  return { error: 'API felló: ' + e.message };
}

if (!Array.isArray(data) || data.length === 0) {
  return { error: 'Sin datos', since: since };
}

let sent = 0;
for (const item of data) {
  if (sent >= 5) break;

  const searchText = ((item.descripcion_del_proceso || '') + ' ' + (item.nombre_entidad || '') + ' ' + (item.tipo_de_contrato || '')).toLowerCase();
  const matched = KEYWORDS.filter(function(kw) { return searchText.indexOf(kw) !== -1; });

  if (matched.length === 0) continue;

  const valor = parseInt(item.valor_del_contrato) || 0;
  const valorFmt = new Intl.NumberFormat('es-CO', { style:'currency', currency:'COP', minimumFractionDigits:0 }).format(valor);
  const fecha = (item.fecha_de_firma || '').split('T')[0];
  const desc = (item.descripcion_del_proceso || '').substring(0, 120);

  const text = '📋 *Licitacion SECOP*\n\n🏛️ *' + item.nombre_entidad + '*\n📍 ' + (item.departamento || '') + ', ' + (item.ciudad || '') + '\n📝 ' + desc + '...\n💰 ' + valorFmt + '\n📅 ' + fecha + '\n🏷️ ' + (item.modalidad_de_contratacion || '') + '\n🔑 ' + matched.slice(0,3).join(', ') + '\n\n🔗 ' + (item.urlproceso?.url || 'https://community.secop.gov.co/') + '\n\n⚡ SECOP Alertas';

  try {
    await http({
      method:'POST',
      url:'http://148.230.90.171:8096/message/sendText/wasapea-7c7a2c6c',
      headers:{ 'apikey':'wasapea-evo-key-2026', 'Content-Type':'application/json' },
      body:{ number:'573106055920', text: text }
    });
    sent++;
  } catch(e) {
    // skip
  }
}

return { sent: sent, total: data.length, since: since };
